head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.file_flag = "N";
scwin.gCondStat = "I"; // 디폴트 Insert : 입력가능, Update : 수정가능
scwin.gIsurCd;
scwin.gImprRegDd;
scwin.gImprRegDd2;
scwin.gEmpNo = js_emp_no;
scwin.gGubun; // 계획서 구분(01: 개선계획서, 02: 이행보고서)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // showObj(txb_isurcd, false);    // 히든처리!
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(penel_1);
        scwin.setCode();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_file_save",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_file_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 파일: 가우스헤더 셋팅

        // dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_fileData.insertRow();
        await scwin.initSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35105.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
        txb_file_nm.setValue(inf_find.getValue());
        scwin.file_flag = "Y";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35105.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("등록 성공");
        $c.frame.path("../").fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35105.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("등록 실패");
        await $c.win.alert(trs_Save.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35105.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name img_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_save_onclick = async function() {
    try {
        if (scwin.gCondStat === "U") {
            await scwin.update();
        } else {
            await scwin.save();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35105.img_save_onclick" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35105.img_close_onclick" });
    }
};

/**
 * @method
 * @name img_publ_end_dd_onclick
 * @description img_publ_end_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_publ_end_dd_onclick = function() {
    try {
        popUpCalendar2(edt_publ_end_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35105.img_publ_end_dd_onclick" });
    }
};

/**
 * @method
 * @name txb_file_nm_onclick
 * @description txb_file_nm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_file_nm_onclick = function() {
    try {
        if (txb_file_nm.getValue() !== "") {
            scwin.filedown();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35105.txb_file_nm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name initSearch
 * @description init Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    if (scwin.gGubun === "01") {
        if (scwin.gIsurCd !== "" && scwin.gImprRegDd !== '') {
            // 개선계획서 수정로직

            // 조회 후  수정처리 기능이므로
            scwin.gCondStat = "U";

            //  데이타 조회
            const sbmOptions = {
                id : "sbm_dts_imprschdl_info",
                action : "/PenaltyImposition.do",
                ref : "",
                target : "dts_imprschdl_info=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } else {
        if (scwin.gIsurCd !== "" && scwin.gImprRegDd2 !== '') {
            // 이행보고서 수정로직

            // 조회 후  수정처리 기능이므로
            scwin.gCondStat = "U";

            //  데이타 조회
            const sbmOptions = {
                id : "sbm_dts_imprschdl_info",
                action : "/PenaltyImposition.do",
                ref : "",
                target : "dts_imprschdl_info=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    }
};

/**
 * @method
 * @name save
 * @description 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 등록
    // 초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd === "") {
        await $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }
    if (edt_publ_end_dd.getValue() === "") {
        await $c.win.alert("배포종료일을 입력하세요.");
        edt_publ_end_dd.focus();
        return;
    }
    if (edt_reg_dd.getValue() > edt_publ_end_dd.getValue()) {
        await $c.win.alert('배포종료일을 등록일보다 큰 일자로 입력하세요');
        edt_publ_end_dd.focus();
        return;
    }
    if (txb_file_nm.getValue() === "") {
        await $c.win.alert("첨부파일을  입력해주세요");
        inf_find.focus();
        return;
    }
    if (txb_file_nm.getValue().length > 80) {
        await $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_file_save.setCellData(1, "PUBL_END_DD", edt_publ_end_dd.getValue());

    // 2015.10.26 이민철

    let vAnswer;
    let vmethod;
    if (scwin.gGubun === "01") {
        vAnswer = confirm('개선계획서를 저장 하시겠습니까?');
        vmethod = "registerImprSchdlFile";
    } else {
        vAnswer = confirm('이행보고서를 저장 하시겠습니까?');
        vmethod = "registerImprPerfmDtlFile";
    }
    if (vAnswer === true) {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/PenaltyImposition.do",
            ref : "dts_file_save,dts_fileData",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name update
 * @description 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    //  수정
    let vUpdateTp; // 수정형태 : 1=배포종료일만수정, 2=첨부파일도 수정

    // 초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd === "") {
        await $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }
    if (edt_publ_end_dd.getValue() === "") {
        await $c.win.alert("배포종료일을 입력하세요.");
        edt_publ_end_dd.focus();
        return;
    }
    if (edt_reg_dd.getValue() > edt_publ_end_dd.getValue()) {
        await $c.win.alert('배포종료일을 등록일보다 큰 일자로 입력하세요');
        edt_publ_end_dd.focus();
        return;
    }
    if (txb_file_nm.getValue() === "") {
        await $c.win.alert("첨부파일을  입력해주세요");
        inf_find.focus();
        return;
    }
    if (txb_file_nm.getValue().length > 80) {
        await $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }

    // 첨부파일은 그대로 배포종료일만 수정한 경우
    if (dts_fileData.getCellData(1, "fileUrl") === '') {
        vUpdateTp = '1';
    } else {
        vUpdateTp = '2';
    }

    // 2015.10.26 이민철

    let vAnswer;
    let vmethod;
    let vImprRegDd;
    if (scwin.gGubun === "01") {
        vAnswer = confirm('개선계획서를 수정 하시겠습니까?');
        vmethod = "modifyImprSchdlFile";
        vImprRegDd = scwin.gImprRegDd;
    } else {
        vAnswer = confirm('이행보고서를 수정 하시겠습니까?');
        vmethod = "modifyImprPerfmDtlFile";
        vImprRegDd = scwin.gImprRegDd2;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "IMPR_REG_DD", vImprRegDd);
    dts_file_save.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_file_save.setCellData(1, "PUBL_END_DD", edt_publ_end_dd.getValue());
    dts_file_save.setCellData(1, "UPDATE_TP", vUpdateTp);
    if (vAnswer === true) {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/PenaltyImposition.do",
            ref : "dts_file_save,dts_fileData",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // gIsurCd = frame.Provider("../").txb_isurcd.value;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    scwin.gImprRegDd = $c.frame.path("../").scwin.gImprRegDd;
    scwin.gImprRegDd2 = $c.frame.path("../").scwin.gImprRegDd2;
    // 계획서 구분(01: 개선계획서, 02: 이행보고서)
    scwin.gGubun = $c.frame.path("../").gUploadGubun;
    edt_reg_dd.setValue($c.ut.cGetToday("yyyymmdd"));
    txb_emp_nm.setValue(js_emp_nm);
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function() {
    const vRegDd = dts_imprschdl_info.getCellData(1, "IMPR_REG_DD");
    const link = "/filedownload.do?REG_DD=" + vRegDd + "&ISUR_CD=" + scwin.gIsurCd + "&gubun=10" + "&SCREN_ID=" + 'ULDSTF35105.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};
